314				if !strings.Contains(inputErr.Reason, "invalid JSON") {
315					t.Errorf("reason = %q, want the existing invalid JSON record reason", inputErr.Reason)
316				}
317				if stdout != "" || stderr != "" {
318					t.Errorf("fatal first record must output nothing, got stdout=%q stderr=%q", stdout, stderr)
319				}
320			})
321		}
322	
323		// Line accounting with prior output retained: a legal escaped newline in
324		// the key is still one physical line and must not shift later numbers;
325		// the blank line 3 counts; the fatal record is line 5; line 6 is never
326		// read and later windows stay open.
327		input := strings.Join([]string{
328			`{"type":"event","key":"k","time":100,"value":2}`,    // line 1
329			`{"type":"event","key":"a\nb","time":200,"value":3}`, // line 2: legal escaped LF in key, one physical line
330			``,                                 // line 3: blank, still counted
