369	// parseResultLines splits stdout into its physical result lines and decodes
370	// each as a complete JSON AggregateResult. Any embedded raw line-control byte
371	// or extra/missing escaping surfaces here as a line count mismatch or a parse
372	// failure.
373	func parseResultLines(t *testing.T, stdout string) []AggregateResult {
374		t.Helper()
375		body := strings.TrimSuffix(stdout, "\n")
376		if body == "" {
377			return nil
378		}
