package edgefleet

import (
	"encoding/json"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// These tests pin down what a legal JSON key escape means as it travels
// through the three stages that touch it: reading the line-delimited record,
// grouping events by the decoded key within a window, and writing the result
// back out as JSON. The same character written with different legal escapes
// must decode to the same key and merge; characters that only look alike after
// a second decode must stay apart; and every result must reparse to the exact
// original key, with embedded line-control characters never breaking the one
// result per physical output line rule. Damaged input (raw control characters
// inside a string, unsupported escapes) stays on the existing fatal input
// error path with the physical line number.

// Equivalent legal spellings of one character decode to the same key, so the
// two events merge into count=2, sum=5 regardless of which spelling arrives
// first. spell1 and spell2 are raw JSON string tokens (quotes included) that
// must both decode to wantKey.
func TestAggregateEquivalentEscapeSpellingsMerge(t *testing.T) {
	cases := []struct {
		name    string
		spell1  string // raw JSON string token, quotes included
		spell2  string // a different legal spelling of the same decoded key
		wantKey string // the decoded Go string
	}{
		{"newline short vs unicode", `"a\nb"`, `"a\u000ab"`, "a\nb"},
		{"carriage return short vs unicode", `"c\rd"`, `"c\u000dd"`, "c\rd"},
		{"tab short vs unicode", `"e\tf"`, `"e\u0009f"`, "e\tf"},
		{"quote short vs unicode", `"g\"h"`, `"g\u0022h"`, "g\"h"},
		{"backslash short vs unicode", `"i\\j"`, `"i\u005cj"`, `i\j`},
		{"slash escaped vs unicode", `"p\/q"`, `"p\u002fq"`, "p/q"},
		{"plain slash vs escaped slash", `"p/q"`, `"p\/q"`, "p/q"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			for _, reverse := range []bool{false, true} {
				t.Run(map[bool]string{false: "forward", true: "reversed"}[reverse], func(t *testing.T) {
					first, second := tc.spell1, tc.spell2
					if reverse {
						first, second = second, first
					}
					input := strings.Join([]string{
						`{"type":"event","key":` + first + `,"time":100,"value":2}`,
						`{"type":"event","key":` + second + `,"time":200,"value":3}`,
						`{"type":"watermark","time":1000}`,
					}, "\n") + "\n"
					stdout, stderr, err := runAggregate(t, input, 1000)
					if err != nil {
						t.Fatalf("unexpected error: %v", err)
					}
					if stderr != "" {
						t.Fatalf("unexpected late log: %q", stderr)
					}
					results := parseResultLines(t, stdout)
					if len(results) != 1 {
						t.Fatalf("equivalent spellings must merge to one key, got %d results:\n%s", len(results), stdout)
					}
					got := results[0]
					if got.Key != tc.wantKey {
						t.Errorf("decoded key = %q, want %q", got.Key, tc.wantKey)
					}
					if got.Start != 0 || got.End != 1000 {
						t.Errorf("window = [%d,%d), want [0,1000)", got.Start, got.End)
					}
					if got.Count != 2 || got.Sum != 5 {
						t.Errorf("count=%d sum=%d, want count=2 sum=5", got.Count, got.Sum)
					}
				})
			}
		})
	}
}

// A key that genuinely contains the two characters backslash and 'n' must not
// be decoded a second time into a newline and merge with the real newline key.
// It is a separate window result, while the short-escape and Unicode-escape
// spellings of a real newline merge.
func TestAggregateLiteralBackslashNStaysDistinctFromNewline(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"a\nb","time":100,"value":2}`,     // real newline (short escape)
		`{"type":"event","key":"a\u000ab","time":200,"value":3}`, // same key via Unicode escape
		`{"type":"event","key":"a\\nb","time":300,"value":7}`,    // backslash + 'n': a different key
		`{"type":"watermark","time":1000}`,
	}, "\n") + "\n"
	stdout, _, err := runAggregate(t, input, 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	results := parseResultLines(t, stdout)
	want := []AggregateResult{
		{Key: "a\nb", Start: 0, End: 1000, Count: 2, Sum: 5}, // 0x0a sorts before 0x5c
		{Key: `a\nb`, Start: 0, End: 1000, Count: 1, Sum: 7},
	}
	if len(results) != len(want) {
		t.Fatalf("got %d results, want %d:\n%s", len(results), len(want), stdout)
	}
	for i := range want {
		if results[i] != want[i] {
			t.Errorf("result %d = %+v, want %+v", i, results[i], want[i])
		}
	}
	// Lock the wire encoding too: a real newline is an escaped \n on output,
	// a real backslash is escaped as \\, so the two lines never look alike.
	wantOut := strings.Join([]string{
		`{"key":"a\nb","start":0,"end":1000,"count":2,"sum":5}`,
		`{"key":"a\\nb","start":0,"end":1000,"count":1,"sum":7}`,
		``,
	}, "\n")
	if stdout != wantOut {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, wantOut)
	}
}

// Keys containing newline, carriage return, tab, quote, NUL, single and
// consecutive backslashes -- including special characters at the very end of
// the key -- each produce exactly one complete physical output line, whose
// JSON decodes back to the exact original key. The output must not keep just
// the visible part or add/drop a layer of escaping. Results still close in
// decoded-key UTF-8 byte order.
func TestAggregateSpecialKeysRoundTripOnePhysicalLineEach(t *testing.T) {
	cases := []struct {
		name    string
		literal string // raw JSON string token fed in, quotes included
		wantKey string // decoded Go string that must come back out
	}{
		{"embedded newline", `"a\nb"`, "a\nb"},
		{"embedded carriage return", `"c\rd"`, "c\rd"},
		{"embedded tab", `"e\tf"`, "e\tf"},
		{"embedded quote", `"g\"h"`, `g"h`},
		{"embedded backslash", `"i\\j"`, `i\j`},
		{"two trailing backslashes", `"dd\\\\"`, `dd\\`},
		{"trailing quote", `"q\""`, `q"`},
		{"trailing newline", `"r\n"`, "r\n"},
		{"trailing nul", `"s\u0000"`, "s\x00"},
		{"trailing carriage return", `"t\r"`, "t\r"},
		{"literal backslash n", `"u\\n"`, `u\n`},
	}
	var lines []string
	for _, tc := range cases {
		lines = append(lines, `{"type":"event","key":`+tc.literal+`,"time":100,"value":1}`)
	}
	lines = append(lines, `{"type":"watermark","time":1000}`)
	stdout, _, err := runAggregate(t, strings.Join(lines, "\n")+"\n", 1000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// One trailing newline per result and nothing else: an embedded raw
	// newline or carriage return would split a result into extra physical
	// lines and fail both this count and the per-line JSON parse below.
	if got := strings.Count(stdout, "\n"); got != len(cases) {
		t.Fatalf("stdout has %d physical line(s), want exactly %d (one per result):\n%q", got, len(cases), stdout)
	}
	body := strings.TrimSuffix(stdout, "\n")
	physicalLines := strings.Split(body, "\n")
	results := parseResultLines(t, stdout)
	if len(results) != len(cases) {
		t.Fatalf("got %d results, want %d", len(results), len(cases))
	}

	// Canonical wire form: re-marshalling each decoded result must reproduce
	// the exact physical line. This fails if the output embedded a raw
	// line-control byte or added/dropped a layer of escaping -- that would
	// either no longer split 1:1 here or marshal back to different bytes.
	for i, r := range results {
		canonical, err := json.Marshal(r)
		if err != nil {
			t.Fatalf("re-marshal result %d: %v", i, err)
		}
		if physicalLines[i] != string(canonical) {
			t.Errorf("physical line %d is not canonical JSON for its key:\n got %s\nwant %s", i+1, physicalLines[i], canonical)
		}
	}

	// Order must be the decoded keys' UTF-8 byte order.
	var sortedKeys []string
	for _, tc := range cases {
		sortedKeys = append(sortedKeys, tc.wantKey)
	}
	sort.Strings(sortedKeys)
	for i, r := range results {
		if r.Key != sortedKeys[i] {
			t.Errorf("position %d key = %q, want %q in UTF-8 byte order (full order: %q)", i, r.Key, sortedKeys[i], sortedKeys)
		}
	}

	// Every output key must reparsed to the exact key that went in.
	byKey := make(map[string]AggregateResult, len(results))
	for _, r := range results {
		byKey[r.Key] = r
	}
	for _, tc := range cases {
		r, ok := byKey[tc.wantKey]
		if !ok {
			t.Errorf("result for key %q is missing (no output key round-tripped to it)", tc.wantKey)
			continue
		}
		if r.Count != 1 || r.Sum != 1 || r.Start != 0 || r.End != 1000 {
			t.Errorf("result for key %q = %+v, want count=1 sum=1 in [0,1000)", tc.wantKey, r)
		}
	}

	// Lock the exact wire form at the tricky tail positions: consecutive
	// backslashes need doubling, a real newline/trailing CR stay escaped, and
	// NUL uses its Unicode escape -- none of these may be a raw byte.
	for _, fragment := range []string{
		`"key":"dd\\\\",`,  // two decoded trailing backslashes -> four on the wire
		`"key":"r\n",`,     // trailing real newline -> escaped
		`"key":"t\r",`,     // trailing real CR -> escaped
		`"key":"s\u0000",`, // trailing NUL -> Unicode escape
	} {
		if !strings.Contains(stdout, fragment) {
			t.Errorf("stdout missing wire fragment %s:\n%s", fragment, stdout)
		}
	}
	// No individual result line may carry a raw C0 control byte (0x00-0x1F):
	// an embedded newline, CR or NUL must stay escaped and can never split a
	// result into more than one physical output line.
	for i, line := range physicalLines {
		for _, c := range []byte(line) {
			if c < 0x20 {
				t.Errorf("physical line %d contains raw control byte 0x%02x:\n%q", i+1, c, line)
			}
		}
	}
}

// When the same keys close at the same time, their order follows the decoded
// keys' UTF-8 bytes no matter which legal escape spelling was used nor the
// order events arrived in.
func TestAggregateEscapeSpellingAndArrivalDoNotAffectOrder(t *testing.T) {
	// The newline key appears once via the short escape and once via the
	// Unicode escape; those two events merge, leaving the five decoded keys
	// regardless of arrival order.
	build := func(tokens []string) string {
		var ls []string
		for i, tok := range tokens {
			ls = append(ls, `{"type":"event","key":`+tok+`,"time":100,"value":`+strconv.Itoa(i+1)+`}`)
		}
		ls = append(ls, `{"type":"watermark","time":1000}`)
		return strings.Join(ls, "\n") + "\n"
	}
	const (
		nul      = `"\u0000z"`
		newlineS = `"\nz"`     // real newline, short escape
		newlineU = `"\u000az"` // same key, Unicode escape
		ascii    = `"az"`
		eacute   = `"\u00e9z"` // é via Unicode escape
		multi    = `"中z"`      // multibyte literal
	)
	shuffles := map[string][]string{
		"desc":  {multi, eacute, ascii, newlineS, nul},
		"asc":   {nul, newlineU, ascii, eacute, multi},
		"mixed": {ascii, nul, multi, newlineS, eacute},
	}
	wantKeys := []string{"\x00z", "\nz", "az", "éz", "中z"}
	for name, tokens := range shuffles {
		t.Run(name, func(t *testing.T) {
			stdout, _, err := runAggregate(t, build(tokens), 1000)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			results := parseResultLines(t, stdout)
			if len(results) != len(wantKeys) {
				t.Fatalf("got %d results, want %d (the two newline spellings must merge):\n%s", len(results), len(wantKeys), stdout)
			}
			for i, want := range wantKeys {
				if results[i].Key != want {
					t.Errorf("position %d key = %q, want %q\nfull output:\n%s", i, results[i].Key, want, stdout)
				}
			}
		})
	}
}

// The legal/illegal boundary stays exactly where JSON draws it: a raw control
// character sitting inside the string (which for a raw newline also splits the
// record across two physical lines) and an escape JSON does not support are
// fatal record errors on the existing path, carrying the physical input line
// number. A newline produced by a legal escape occupies one physical line and
// therefore does not advance the line count; blank lines still count.
func TestAggregateRawControlAndUnsupportedEscapeAreFatal(t *testing.T) {
	cases := []struct {
		name     string
		record   string // the offending physical input (a raw newline case is two physical lines)
		wantLine int
	}{
		{"raw tab in string", "{\"type\":\"event\",\"key\":\"a\tb\",\"time\":1,\"value\":1}", 1},
		{"raw carriage return in string", "{\"type\":\"event\",\"key\":\"a\rb\",\"time\":1,\"value\":1}", 1},
		{"raw nul in string", "{\"type\":\"event\",\"key\":\"a\x00b\",\"time\":1,\"value\":1}", 1},
		{"raw newline in string splits the record", "{\"type\":\"event\",\"key\":\"a\nb\",\"time\":1,\"value\":1}", 1},
		{"unsupported escape x", `{"type":"event","key":"a\xb","time":1,"value":1}`, 1},
		{"unsupported escape o", `{"type":"event","key":"a\ob","time":1,"value":1}`, 1},
		{"non-hex unicode escape", `{"type":"event","key":"a\u00g0b","time":1,"value":1}`, 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			input := tc.record + "\n"
			stdout, stderr, err := runAggregate(t, input, 1000)
			inputErr, ok := err.(*InputError)
			if !ok {
				t.Fatalf("want *InputError, got %T: %v", err, err)
			}
			if inputErr.Line != tc.wantLine {
				t.Errorf("line = %d, want %d", inputErr.Line, tc.wantLine)
			}
			if !strings.Contains(inputErr.Reason, "invalid JSON") {
				t.Errorf("reason = %q, want the existing invalid JSON record reason", inputErr.Reason)
			}
			if stdout != "" || stderr != "" {
				t.Errorf("fatal first record must output nothing, got stdout=%q stderr=%q", stdout, stderr)
			}
		})
	}

	// Line accounting with prior output retained: a legal escaped newline in
	// the key is still one physical line and must not shift later numbers;
	// the blank line 3 counts; the fatal record is line 5; line 6 is never
	// read and later windows stay open.
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":100,"value":2}`,    // line 1
		`{"type":"event","key":"a\nb","time":200,"value":3}`, // line 2: legal escaped LF in key, one physical line
		``,                                 // line 3: blank, still counted
		`{"type":"watermark","time":1000}`, // line 4: closes [0,1000), both keys
		`{"type":"event","key":"o\ops","time":1,"value":1}`, // line 5: unsupported escape, fatal
		`{"type":"watermark","time":2000}`,                  // line 6: never read
	}, "\n") + "\n"
	stdout, stderr, err := runAggregate(t, input, 1000)
	if err == nil {
		t.Fatal("expected a fatal error for the unsupported escape")
	}
	inputErr, ok := err.(*InputError)
	if !ok {
		t.Fatalf("want *InputError, got %T: %v", err, err)
	}
	if inputErr.Line != 5 {
		t.Fatalf("line = %d, want 5 (legal key escapes add no input line; blank line 3 counts)", inputErr.Line)
	}
	if !strings.Contains(inputErr.Reason, "invalid JSON") {
		t.Fatalf("reason = %q, want the invalid JSON record reason", inputErr.Reason)
	}
	if stderr != "" {
		t.Errorf("fatal record produces no late notice, got %q", stderr)
	}
	// Exactly the two results closed at line 4 survive, including the key
	// whose newline came from a legal escape, proving it aggregated normally.
	results := parseResultLines(t, stdout)
	want := []AggregateResult{
		{Key: "a\nb", Start: 0, End: 1000, Count: 1, Sum: 3},
		{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
	}
	if len(results) != len(want) {
		t.Fatalf("got %d surviving results, want %d:\n%s", len(results), len(want), stdout)
	}
	for i := range want {
		if results[i] != want[i] {
			t.Errorf("surviving result %d = %+v, want %+v", i, results[i], want[i])
		}
	}
}

// parseResultLines splits stdout into its physical result lines and decodes
// each as a complete JSON AggregateResult. Any embedded raw line-control byte
// or extra/missing escaping surfaces here as a line count mismatch or a parse
// failure.
func parseResultLines(t *testing.T, stdout string) []AggregateResult {
	t.Helper()
	body := strings.TrimSuffix(stdout, "\n")
	if body == "" {
		return nil
	}
	var results []AggregateResult
	for i, line := range strings.Split(body, "\n") {
		var r AggregateResult
		if err := json.Unmarshal([]byte(line), &r); err != nil {
			t.Fatalf("physical output line %d is not a complete JSON object: %v\nraw stdout: %q", i+1, err, stdout)
		}
		results = append(results, r)
	}
	return results
}

package main

import (
	"bytes"
	"encoding/json"
	"sort"
	"strings"
	"testing"
)

// These tests drive the real aggregate command end to end to guard what a
// legal JSON key escape means on the wire: reading the record, grouping by the
// decoded key within one fixed window, and writing one JSON result per
// physical output line. The same character written with different legal
// escapes must merge; a literal backslash-n must stay distinct; and keys
// carrying line-control characters must still occupy exactly one output line
// that reparses to the original key. Damaged input stays on the existing
// fatal path with the physical input line number.

// TestAggregateCLIKeyEscapeSpellingsMerge is the headline case at window
// length 1000ms with every event time in the first window: a real newline
// written with the short escape and with the Unicode escape is the same key,
// so its two events (values 2 and 3) close as count=2, sum=5. A key that
// actually stores backslash and 'n' is a different key and must not be decoded
// a second time into the newline key; a plain slash and an escaped slash are
// likewise one key.
func TestAggregateCLIKeyEscapeSpellingsMerge(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"a\nb","time":100,"value":2}`,     // real newline, short escape
		`{"type":"event","key":"a\u000ab","time":200,"value":3}`, // same key, Unicode escape
		`{"type":"event","key":"a\\nb","time":300,"value":7}`,    // backslash + 'n': separate key
		`{"type":"event","key":"p/q","time":400,"value":4}`,      // plain slash
		`{"type":"event","key":"p\/q","time":500,"value":9}`,     // escaped slash: same key
		`{"type":"watermark","time":1000}`,
	}, "\n") + "\n"

	cmd := aggregateCommand(t, input, "--window-ms", "1000")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("aggregate failed: %v\nstderr: %s", err, stderr.String())
	}
	if code := cmd.ProcessState.ExitCode(); code != 0 {
		t.Fatalf("exit code = %d, want 0", code)
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", stderr.String())
	}

	assertWindowLines(t, stdout.String(), []windowLine{
		{Key: "a\nb", Start: 0, End: 1000, Count: 2, Sum: 5},
		{Key: `a\nb`, Start: 0, End: 1000, Count: 1, Sum: 7},
		{Key: "p/q", Start: 0, End: 1000, Count: 2, Sum: 13},
	})

	// The newline key's output keeps the newline escaped, so it is one
	// physical line; the literal backslash-n key shows a doubled backslash and
	// can never be confused with the first line.
	want := strings.Join([]string{
		`{"key":"a\nb","start":0,"end":1000,"count":2,"sum":5}`,
		`{"key":"a\\nb","start":0,"end":1000,"count":1,"sum":7}`,
		`{"key":"p/q","start":0,"end":1000,"count":2,"sum":13}`,
		``,
	}, "\n")
	if stdout.String() != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout.String(), want)
	}
}

// TestAggregateCLIKeyWithLineControlsIsOnePhysicalLine proves that special
// characters inside a key -- newline, carriage return, tab, quote, NUL and
// trailing/consecutive backslashes -- neither delete nor replace characters
// and cannot split one result across multiple physical output lines. Each
// output line is complete JSON that decodes back to the exact input key, and
// several keys closing together stay in decoded-key UTF-8 byte order.
func TestAggregateCLIKeyWithLineControlsIsOnePhysicalLine(t *testing.T) {
	type row struct {
		token string // raw JSON string token, quotes included
		key   string // decoded key expected back on output
	}
	rows := []row{
		{`"a\nb"`, "a\nb"},
		{`"c\rd"`, "c\rd"},
		{`"e\tf"`, "e\tf"},
		{`"g\"h"`, `g"h`},
		{`"i\\j"`, `i\j`},
		{`"dd\\\\"`, `dd\\`},   // two trailing backslashes
		{`"r\n"`, "r\n"},       // trailing newline
		{`"t\r"`, "t\r"},       // trailing carriage return
		{`"s\u0000"`, "s\x00"}, // trailing NUL
	}
	var lines []string
	for _, r := range rows {
		lines = append(lines, `{"type":"event","key":`+r.token+`,"time":100,"value":1}`)
	}
	lines = append(lines, `{"type":"watermark","time":1000}`)
	input := strings.Join(lines, "\n") + "\n"

	cmd := aggregateCommand(t, input, "--window-ms", "1000")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("aggregate failed: %v\nstderr: %s", err, stderr.String())
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", stderr.String())
	}

	got := stdout.String()
	// Exactly one trailing newline per result: a raw LF or CR inside a key
	// would split a result and raise this physical-line count.
	if n := strings.Count(got, "\n"); n != len(rows) {
		t.Fatalf("stdout has %d physical line(s), want %d (one result each):\n%q", n, len(rows), got)
	}
	physical := strings.Split(strings.TrimSuffix(got, "\n"), "\n")
	if len(physical) != len(rows) {
		t.Fatalf("got %d physical lines, want %d", len(physical), len(rows))
	}
	// No physical result line carries a raw control byte; every one is full
	// JSON that re-marshals to identical canonical bytes.
	var decoded []windowLine
	for i, text := range physical {
		for _, c := range []byte(text) {
			if c < 0x20 {
				t.Errorf("physical line %d has raw control byte 0x%02x:\n%q", i+1, c, text)
			}
		}
		var wl windowLine
		if err := json.Unmarshal([]byte(text), &wl); err != nil {
			t.Fatalf("physical line %d is not complete JSON: %v\n%q", i+1, err, text)
		}
		decoded = append(decoded, wl)
	}

	// Expected order is decoded-key UTF-8 byte order; sort a copy of the
	// input keys to derive it rather than hard-coding it.
	wantKeys := make([]string, len(rows))
	for i, r := range rows {
		wantKeys[i] = r.key
	}
	sort.Strings(wantKeys)
	for i, wl := range decoded {
		if wl.Key != wantKeys[i] {
			t.Errorf("position %d key = %q, want %q (decoded UTF-8 order %q)", i, wl.Key, wantKeys[i], wantKeys)
		}
		if wl != (windowLine{Key: wl.Key, Start: 0, End: 1000, Count: 1, Sum: 1}) {
			t.Errorf("result for key %q = %+v, want count=1 sum=1 in [0,1000)", wl.Key, wl)
		}
	}
}

// TestAggregateCLIRawControlAndBadEscapeAreFatal keeps the legal/corrupt
// boundary where JSON draws it: a raw control character inside the string (a
// raw newline also breaks the record across two physical lines) and an escape
// JSON does not support are fatal, report the physical input line and reason,
// exit 1, and stop before later records, while results already output remain.
// A newline obtained through a legal escape is one physical line and does not
// move later line numbers; the blank line still counts.
func TestAggregateCLIRawControlAndBadEscapeAreFatal(t *testing.T) {
	cases := []struct {
		name   string
		record string
	}{
		{"raw tab", "{\"type\":\"event\",\"key\":\"a\tb\",\"time\":1,\"value\":1}"},
		{"raw carriage return", "{\"type\":\"event\",\"key\":\"a\rb\",\"time\":1,\"value\":1}"},
		{"raw newline splits record", "{\"type\":\"event\",\"key\":\"a\nb\",\"time\":1,\"value\":1}"},
		{"unsupported escape", `{"type":"event","key":"a\xb","time":1,"value":1}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// Line 1 closes a healthy window; line 2 is blank; the bad record
			// is physical line 3; line 4 must never be read.
			input := strings.Join([]string{
				`{"type":"event","key":"ok","time":100,"value":2}`, // line 1
				`{"type":"watermark","time":1000}`,                 // line 2 closes [0,1000)
				``,                                                 // line 3 blank, still counted
				tc.record,                                          // line 4: corrupt
				`{"type":"watermark","time":2000}`,                 // line 5: never read
			}, "\n") + "\n"

			cmd := aggregateCommand(t, input, "--window-ms", "1000")
			var stdout, stderr bytes.Buffer
			cmd.Stdout = &stdout
			cmd.Stderr = &stderr
			if err := cmd.Run(); err == nil {
				t.Fatal("aggregate succeeded, want exit code 1 for corrupt input")
			}
			if code := cmd.ProcessState.ExitCode(); code != 1 {
				t.Fatalf("exit code = %d, want 1", code)
			}
			errText := stderr.String()
			if !strings.Contains(errText, "line 4") {
				t.Errorf("stderr = %q, want it to name physical line 4 (blank line 3 counts)", errText)
			}
			// The healthy window closed on line 2 is retained verbatim.
			assertWindowLines(t, stdout.String(), []windowLine{
				{Key: "ok", Start: 0, End: 1000, Count: 1, Sum: 2},
			})
		})
	}

	// A legal escaped newline in a key stays one physical line, so the later
	// corrupt record lands on line 5 (not shifted), and its own earlier result
	// is retained.
	input := strings.Join([]string{
		`{"type":"event","key":"a\nb","time":100,"value":3}`, // line 1: legal escaped LF, one physical line
		``,                                 // line 2: blank, counts
		`{"type":"watermark","time":1000}`, // line 3 closes [0,1000)
		`{"type":"event","key":"x","time":1100,"value":1}`,  // line 4: later window, stays open
		`{"type":"event","key":"o\ops","time":1,"value":1}`, // line 5: unsupported escape, fatal
		`{"type":"watermark","time":2000}`,                  // line 6 never read
	}, "\n") + "\n"
	cmd := aggregateCommand(t, input, "--window-ms", "1000")
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err == nil {
		t.Fatal("aggregate succeeded, want exit code 1 for the unsupported escape")
	}
	if code := cmd.ProcessState.ExitCode(); code != 1 {
		t.Fatalf("exit code = %d, want 1", code)
	}
	if !strings.Contains(stderr.String(), "line 5") {
		t.Fatalf("stderr = %q, want physical line 5 (a legal key escape adds no input line)", stderr.String())
	}
	assertWindowLines(t, stdout.String(), []windowLine{
		{Key: "a\nb", Start: 0, End: 1000, Count: 1, Sum: 3},
	})
}

package edgefleet

import (
	"bytes"
	"fmt"
	"strings"
	"testing"
	"time"
)

// This file guards the cost of collecting physical lines, not their results.
// The result contract for long records split across arbitrary reads lives in
// aggregate_long_record_test.go and aggregate_chunked_input_test.go. What is
// pinned here is the complexity: when a legal record with a very long key
// arrives one or a few bytes per Read, line collection must cost about one
// newline scan per input byte -- linear in the cumulative input byte count
// and read count -- rather than one scan per Read over the whole accumulated
// tail, which is quadratic in the line length.

// singleByteCuts lists a cut before every byte except the first, the schedule
// that made the old rescanner quadratic.
func singleByteCuts(n int) []int {
	cuts := make([]int, 0, n-1)
	for at := 1; at < n; at++ {
		cuts = append(cuts, at)
	}
	return cuts
}

// bestSingleByteTime measures repeated one-byte-per-Read passes in growing
// batches until a batch spans at least minBatch, returning the best
// (minimum-noise) average per pass. Comparing two streams of the same byte
// length under the same schedule makes the ratio independent of the
// machine's absolute speed.
func bestSingleByteTime(t *testing.T, input string, minBatch time.Duration) time.Duration {
	t.Helper()
	cuts := singleByteCuts(len(input))
	iters := 1
	best := time.Duration(1<<63 - 1)
	for attempt := 0; attempt < 6; attempt++ {
		begin := time.Now()
		for i := 0; i < iters; i++ {
			var out, late bytes.Buffer
			if err := RunAggregate(newChunkReader(input, cuts...), 1000, &out, &late); err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		}
		batch := time.Since(begin)
		if avg := batch / time.Duration(iters); avg < best {
			best = avg
		}
		if batch >= minBatch {
			return best
		}
		// Run long enough to rise above scheduler noise, then try again.
		iters *= 4
	}
	return best
}

// TestAggregateLineCollectionCostFollowsBytesNotLineLength is the complexity
// guard. Two inputs have essentially the SAME total byte count and arrive
// through the SAME number of one-byte Reads; they differ only in whether the
// bytes form one very long physical record or thousands of short ones. A
// linear collector scans every byte about once either way (plus read-call
// overhead, identical per byte), so the two timings are comparable. The old
// collector rescanned the whole pending tail after every Read, i.e. about
// L*L/2 comparisons for one L-byte line versus only N*m/2 for N bytes split
// into m-byte lines, making the long-line input hundreds of times slower
// despite the identical byte and read counts.
func TestAggregateLineCollectionCostFollowsBytesNotLineLength(t *testing.T) {
	if testing.Short() {
		t.Skip("timing guard skipped in -short mode")
	}
	const target = 200 * 1024

	// One long event record (long multibyte key) closed by a watermark.
	longKey := longKey(longKeySuffixA, target)
	oneLongLine := strings.Join([]string{
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, longKey),
		`{"type":"watermark","time":1000}`,
		``,
	}, "\n")

	// The same number of bytes as many short newline-terminated records, all
	// merging into one short-key window, closed by a watermark.
	shortRecord := `{"type":"event","key":"短","time":100,"value":1}` + "\n"
	var b strings.Builder
	for b.Len()+len(shortRecord) < target {
		b.WriteString(shortRecord)
	}
	b.WriteString(`{"type":"watermark","time":1000}` + "\n")
	manyShortLines := b.String()

	if len(oneLongLine) < target {
		t.Fatalf("test setup: long input is only %d bytes, want >= %d", len(oneLongLine), target)
	}
	// The two streams must be genuinely the same order of size; otherwise the
	// ratio would measure byte count rather than line layout.
	if got := len(oneLongLine); got > target*2 || got < target {
		t.Fatalf("test setup: long input %d bytes vs short input %d bytes", got, len(manyShortLines))
	}

	// The timed long-line delivery must also stay correct: the whole key
	// survives one-byte arrival and the watermark closes its window.
	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(oneLongLine, singleByteCuts(len(oneLongLine))...), 1000, &out, &late); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	wantWindow := fmt.Sprintf(`{"key":%q,"start":0,"end":1000,"count":1,"sum":7}`+"\n", longKey)
	if out.String() != wantWindow {
		t.Fatalf("single-byte long-line output mismatch:\n got: %q\nwant: %q", out.String(), wantWindow)
	}
	if late.String() != "" {
		t.Fatalf("unexpected late notices: %q", late.String())
	}

	longAvg := bestSingleByteTime(t, oneLongLine, 30*time.Millisecond)
	shortAvg := bestSingleByteTime(t, manyShortLines, 30*time.Millisecond)

	// Linear collection: comparable cost for equal bytes and equal reads.
	// The short stream parses thousands of records (more callbacks), the long
	// stream copies/grows one large buffer (more copies), so either may win;
	// allow a generous factor either way. The quadratic rescanner made the
	// long stream hundreds of times slower.
	const factor = 6.0
	if ratio := float64(longAvg) / float64(shortAvg); ratio > factor {
		t.Fatalf("line collection cost grows with line length at fixed byte/read count: "+
			"one %d-byte line took %v/pass, %d bytes of short lines took %v/pass "+
			"(long/short ratio %.2f, want <= %.1f)",
			len(oneLongLine), longAvg, len(manyShortLines), shortAvg, ratio, factor)
	}
	// Absolute backstop: ~200 KiB delivered one byte at a time must finish
	// promptly with a linear collector, even on a slow, contended machine.
	if longAvg > 2*time.Second {
		t.Fatalf("single-byte processing of %d bytes took %v/pass, want under 2s", len(oneLongLine), longAvg)
	}
}

// TestAggregateLineCollectionAlternatingChunksLinear interleaves long and
// short records and alternates the read size between one byte and a few
// kilobytes, so the cursor that resumes the newline search must repeatedly
// skip already-searched long tails and then find newlines inside freshly
// appended bytes. Output must equal the one-shot reference; this guards
// correctness of the resume cursor under mixed chunking, the timing ratio is
// covered by the test above.
func TestAggregateLineCollectionAlternatingChunksLinear(t *testing.T) {
	keyA := longKey(longKeySuffixA, 64*1024)
	keyB := longKey(longKeySuffixB, 64*1024)
	lines := []string{
		``,
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":2}`, "短"),
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":10}`, keyA),
		`{"type":"watermark","time":500}`,
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, keyB),
		``,
		fmt.Sprintf(`{"type":"event","key":%q,"time":200,"value":4}`, "短"),
		`{"type":"watermark","time":1000}`,
	}
	input := strings.Join(lines, "\n") + "\n"

	var refOut, refLate bytes.Buffer
	if err := RunAggregate(strings.NewReader(input), 1000, &refOut, &refLate); err != nil {
		t.Fatalf("one-shot reference failed: %v", err)
	}

	// Alternating one-byte and 4 KiB cuts.
	var cuts []int
	pos := 0
	small := true
	for pos < len(input) {
		step := 1
		if !small {
			step = 4096
		}
		small = !small
		pos += step
		if pos < len(input) {
			cuts = append(cuts, pos)
		}
	}

	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(input, cuts...), 1000, &out, &late); err != nil {
		t.Fatalf("alternating-chunk run failed: %v", err)
	}
	if out.String() != refOut.String() {
		t.Fatalf("alternating chunks changed the window output:\n got: %q\nwant: %q", out.String(), refOut.String())
	}
	if late.String() != refLate.String() {
		t.Fatalf("alternating chunks changed the late output:\n got: %q\nwant: %q", late.String(), refLate.String())
	}
}

