// in textual order. It exists because decoding into map[string]... silently
// keeps only the last value of a repeated name, which would hide duplicate
// fields; the scan itself reports any syntax error, so malformed JSON still
// fails with the existing format error before members are inspected. Only
// top-level members are materialized: nested objects and arrays are skipped
// over as raw values, so a name inside one of them never counts at the top
// level.
func objectMembers(line string) ([]objectMember, error) {
	dec := json.NewDecoder(strings.NewReader(line))
	dec.UseNumber()
	var members []objectMember

	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, fmt.Errorf("invalid JSON record: expected a JSON object, got %s", describeToken(tok))
