	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, fmt.Errorf("cannot unmarshal %s into Go value of type map[string]json.RawMessage", describeToken(tok))
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		name, ok := keyTok.(string)
		if !ok {
			return nil, fmt.Errorf("invalid JSON record: object key is not a string")
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil, err
		}
		members = append(members, objectMember{Name: name, Raw: raw})
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return nil, err
	}
	if tok, err := dec.Token(); err != io.EOF {
		if err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("invalid JSON record: trailing data after top-level object: %s", describeToken(tok))
	}
	return members, nil
}

// describeToken renders a decoded token for the "expected a JSON object"
// error, matching the wording encoding/json uses for values.
func describeToken(tok json.Token) string {
	switch v := tok.(type) {
	case json.Delim:
		switch v {
		case '[':
			return "["
		case '{':
			return "{"
		}
		return string(v)
	case string:
		return strconv.Quote(v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	case nil:
		return "null"
	case json.Number:
		return v.String()
	default:
		return fmt.Sprintf("%v", v)
	}
}

