			if len(results) != 1 || results[0].Key != "a" || results[0].Count != 1 || results[0].Sum != 1 {
				t.Fatalf("stdout = %q, want exactly one count for top-level key a", stdout)
			}
		})
	}
}

// TestAggregateDuplicateKeyBeatsFieldValidation: the duplicate is rejected
// before either key value is decoded, and before time/value/partition are
// checked. An empty, mistyped or character-damaged occurrence paired with a
// legal one must still report the duplicate, not the value-specific failure.
func TestAggregateDuplicateKeyBeatsFieldValidation(t *testing.T) {
	cases := []struct {
		name   string
		record string
	}{
		{"first key empty, second legal", `{"type":"event","key":"","key":"b","time":100,"value":1}`},
		{"first key mistyped, second legal", `{"type":"event","key":7,"key":"b","time":100,"value":1}`},
		{"first key has unpaired surrogate, second legal", `{"type":"event","key":"a\ud800b","key":"b","time":100,"value":1}`},
		{"first key has raw invalid UTF-8, second legal", "{\"type\":\"event\",\"key\":\"a\xffb\",\"key\":\"b\",\"time\":100,\"value\":1}"},
		{"first legal, second empty", `{"type":"event","key":"b","key":"","time":100,"value":1}`},
		{"first legal, second mistyped", `{"type":"event","key":"b","key":7,"time":100,"value":1}`},
		{"first legal, second surrogate-damaged", `{"type":"event","key":"b","key":"a\ud800z","time":100,"value":1}`},
		{"time also missing", `{"type":"event","key":"a","key":"b","value":1}`},
		{"value also wrong type", `{"type":"event","key":"a","key":"b","time":100,"value":"x"}`},
		{"time out of range as well", `{"type":"event","key":"a","key":"b","time":-5,"value":1}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			input := tc.record + "\n"
			_, stderr, err := runAggregate(t, input, 1000)
			assertDuplicateKeyError(t, err, 1)
			if stderr != "" {
				t.Errorf("fatal record produces no late notice, got %q", stderr)
			}
		})
	}
}

// TestAggregateDuplicateKeyBeatsPartitionFieldCheck uses partitioned mode:
// a duplicate key with the partition missing or out of range still reports the
// duplicate, never the partition field error.
func TestAggregateDuplicateKeyBeatsPartitionFieldCheck(t *testing.T) {
	cases := []struct {
		name   string
		record string
	}{
		{"partition missing", `{"type":"event","key":"a","key":"b","time":100,"value":1}`},
		{"partition out of range", `{"type":"event","key":"a","key":"b","time":100,"value":1,"partition":9}`},
		{"partition mistyped", `{"type":"event","key":"a","key":"b","time":100,"value":1,"partition":"x"}`},
